// Error Trigger payload: { execution: { id, url, error, lastNodeExecuted, mode }, workflow }
// or, when the trigger itself failed: { trigger: { error, mode }, workflow }.
const p = $json;
const ex = p.execution || {};
const err = ex.error || (p.trigger && p.trigger.error) || {};
const msg = [err.message, err.description].filter(Boolean).join(' – ') || 'No error message';
return [{ json: {
  kind: 'crash',
  workflow: (p.workflow || {}).name || '?',
  workflow_id: (p.workflow || {}).id || null,
  execution_id: ex.id || null,
  step: (err.node && err.node.name) || ex.lastNodeExecuted || (p.trigger ? 'trigger' : '?'),
  error: String(msg).slice(0, 1500),
  mode: ex.mode || (p.trigger || {}).mode || null,
} }];

// Find the studio in the failed run's data (best effort; the API key may be missing).
const base = $('Failed run').item.json;
const run = $json || {};
let name = null, slug = null, ref = null;
const fromRe = /^\s*"?([^"<]+?)"?\s*<[^>]*@send\.studiohiruko\.com>/;
let budget = 20000;
const walk = (v, depth) => {
  if (!v || typeof v !== 'object' || depth > 12 || --budget < 0) return;
  for (const [k, x] of Object.entries(v)) {
    if (typeof x === 'string') {
      if (!name && (k === 'studio' || k === 'studio_name')) name = x;
      else if (!slug && (k === 'slug' || k === 'client_slug' || k === 'p_client_slug')) slug = x;
      else if (!name && k === 'from') { const m = x.match(fromRe); if (m && !/Studio Hiruko/.test(m[1])) name = m[1].trim(); }
      else if (!ref && (k === 'lead_id' || k === 'p_lead_id')) ref = 'lead ' + x;
    } else if (x && typeof x === 'object') {
      if (!name && k === 'client' && typeof x.name === 'string') name = x.name;
      walk(x, depth + 1);
    }
  }
};
const runData = run.data && run.data.resultData && run.data.resultData.runData;
if (runData) walk(runData, 0);
const studio = name && slug ? name + ' (' + slug + ')' : (name || slug ||
  (runData ? 'not found in run data' : 'unknown (could not read the run)'));
return [{ json: { ...base, studio, ref } }];

// Called by a workflow branch that handled a failure and carried on.
return $input.all().map((item) => {
  const a = item.json.alert || item.json;
  return { json: {
    kind: 'handled', workflow: a.workflow || '?', workflow_id: a.workflow_id || null,
    execution_id: a.execution_id || null, step: a.step || '?', error: a.error || '?',
    studio: a.studio || 'unknown', ref: a.ref || null,
  } };
});

// Build the alert email. Throttle: the same workflow + step + error at most once
// an hour, and 20 alerts a day in all, so a failing schedule can't use up the
// Resend quota the studios' emails depend on.
const TO = '<email>', FROM = 'Studio Hiruko alerts <<email>>';
const s = $getWorkflowStaticData('global');
const now = Date.now();
const day = new Date().toISOString().slice(0, 10);
if (s.day !== day) { s.day = day; s.count = 0; }
s.seen = s.seen || {};
for (const [k, v] of Object.entries(s.seen)) if (now - v.at > 3600e3 && !v.held) delete s.seen[k];

const out = [];
for (const item of $input.all()) {
  const a = item.json;
  const cleanStudio = String(a.studio || 'unknown').replace(/\s*<[^>]*>\s*$/, '').replace(/^"|"$/g, '');
  const key = [a.workflow, a.step, String(a.error).slice(0, 120)].join('|');
  const prev = s.seen[key];
  if (prev && now - prev.at < 3600e3) { prev.held = (prev.held || 0) + 1; continue; }
  if (s.count >= 20) continue;
  const held = prev && prev.held ? prev.held : 0;
  s.seen[key] = { at: now, held: 0 };
  s.count += 1;
  const link = a.workflow_id && a.execution_id
    ? 'https://<n8n-host>/workflow/' + a.workflow_id + '/executions/' + a.execution_id : 'n/a';
  const when = new Date().toLocaleString('en-GB', { timeZone: 'Europe/London' });
  const text = [
    a.kind === 'crash' ? 'An n8n run failed and stopped.' : 'An n8n run hit a failure and carried on (the studio may need to reply personally).',
    '',
    'Workflow:     ' + a.workflow,
    'Studio:       ' + cleanStudio,
    'Failing step: ' + a.step,
    'Reference:    ' + (a.ref || 'n/a'),
    'When:         ' + when + ' (London)',
    '',
    'Error:',
    a.error,
    '',
    'Open the run: ' + link,
    held ? '\n' + held + ' more of the same in the last hour were not emailed.' : null,
    '',
    'Same workflow, step and error: at most one email an hour, and 20 a day in all.',
  ].filter((l) => l !== null).join('\n');
  out.push({ json: { resend_request: {
    from: FROM, to: [TO],
    subject: 'Alert: ' + a.workflow + ' – ' + a.step + (cleanStudio && !/^unknown|^not found/.test(cleanStudio) ? ' – ' + cleanStudio : ''),
    text,
    tags: [{ name: 'kind', value: 'error_alert' }],
  } } });
}
return out;
